	/**  Cached cover URL. */
	albumArt?: string | null,
	/**  Integrated loudness (LUFS). */
	loudnessLufs?: number | null,
	/**  Favourite flag. */
	isFavorite?: boolean | null,
	/**  Lifetime play count. */
	playCount?: number | null,
