/**  A persisted smart playlist row, with `rules` parsed back into structured form. */
export type SmartPlaylist = {
	/**  Primary key (UUID v4). */
	id: string,
	/**  Display name. */
	name: string,
	/**  Free-text description; nullable in SQLite, and nullable on the wire. */
	description: string | null,
	/**  How the rules combine. */
	matchType: SmartPlaylistMatchType,
	/**  The rules themselves. */
	rules: SmartPlaylistRule[],
	/**  ISO-8601 creation timestamp. */
	createdAt: string,
	/**  ISO-8601 last-update timestamp. */
	updatedAt: string,
};

/**  The persisted rule definition, stored JSON-serialized in the `rules` column. */
export type SmartPlaylistDefinition = {
	/**  How the rules combine. */
	matchType: SmartPlaylistMatchType,
	/**  The rules themselves. An empty list matches the whole library. */
	rules: SmartPlaylistRule[],
};

/**
 *  Track columns a rule can match against.
 * 
 *  The TypeScript source keeps this as one `SMART_PLAYLIST_FIELDS` tuple from
 *  which the union, the zod enum and the renderer's per-field operator map are
 *  all derived. The Rust enum is that single source of truth.
 */
export type SmartPlaylistField = 
/**  `tracks.genre`. */
"genre" | 
/**  `tracks.artist`. */
"artist" | 
/**  `tracks.album`. */
"album" | 
/**  `tracks.title`. */
"title" | 
/**  `tracks.year`. */
"year" | 
/**  `tracks.play_count`. */
"playCount" | 
/**  `tracks.is_favorite`. */
"isFavorite" | 
/**  `tracks.created_at`. */
"dateAdded";

/**  How multiple rules combine. */
export type SmartPlaylistMatchType = 
/**  Every rule must match (SQL `AND`). */
"all" | 
/**  Any rule may match (SQL `OR`). */
"any";

/**  Comparison operators. Applicability depends on the field's type. */
export type SmartPlaylistOperator = 
/**  Exact equality. */
"is" | 
/**  Exact inequality. */
"isNot" | 
/**  Substring match (`LIKE`, with the `ESCAPE '\'` guard). */
"contains" | 
/**  Strictly greater than. */
"greaterThan" | 
/**  Strictly less than. */
"lessThan" | 
/**  Inclusive range across `value` (lower) and `value_to` (upper). */
"between" | 
/**  `date_added` within the last `value` days. */
"inLastDays";

/**
 *  A single rule.
 * 
 *  `value` / `value_to` semantics depend on the operator:
 *  - [`SmartPlaylistOperator::Between`] uses both, as lower and upper bound.
 *  - [`SmartPlaylistOperator::InLastDays`] reads `value` as a day count.
 *  - [`SmartPlaylistField::IsFavorite`] reads `value` as `"true"` / `"false"`.
 *  - everything else compares `value` against the field.
 * 
 *  The value stays a `String` on purpose — it is a heterogeneously-typed literal
 *  the renderer builds from a text input, and Phase 7 parses it per operator.
 */
export type SmartPlaylistRule = {
	/**  Column to match against. */
	field: SmartPlaylistField,
	/**  Comparison to apply. */
	operator: SmartPlaylistOperator,
	/**  Primary operand. */
	value: string,
	/**  Upper bound, for [`SmartPlaylistOperator::Between`] only. */
	valueTo?: string | null,
};

/**
 *  A one-off notice from a background subsystem.
 * 
 *  `code` is a stable identifier the renderer maps to a translated string; it is
 *  a free-form `String` on the wire because the producing subsystem owns its own
 *  code vocabulary. Unknown codes fall back to a generic message rather than
 *  being dropped.
 */
export type SystemNotice = {
	/**  Which subsystem raised it. */
	source: SystemNoticeSource,
	/**  How loudly to surface it. */
	level: SystemNoticeLevel,
	/**  Stable identifier; the renderer maps this to an i18n key. */
	code: string,
	/**
	 *  Interpolation values for the translated message.
	 * 
	 *  A `BTreeMap` rather than a `HashMap` so the serialized key order is
	 *  stable — a payload that reorders itself between emissions would defeat
	 *  any downstream de-duplication that hashes it.
	 */
	meta?: { [key in string]: NoticeMetaValue } | null,
};

/**  A system notice, deduplicated per `source:code` for five minutes. */
export type SystemNoticeEmitted = SystemNotice;

/**  How loudly the renderer should surface a notice. */
export type SystemNoticeLevel = 
/**  Rendered as an error toast. */
"error" | 
/**  Rendered as a warning toast. Every notice v1 emitted was this. */
"warn" | 
/**  Rendered as an info toast. */
"info";

/**
 *  Which subsystem raised a notice.
 * 
 *  A closed set, not a free-form string: the renderer maps `source:code` pairs
 *  onto i18n keys, so a source it has never heard of has nothing to display.
 */
export type SystemNoticeSource = 
/**  Discord Rich Presence. */
"discord" | 
/**  The album-art cache. */
"album-art";

/**  An external binary the downloader depends on. */
export type Tool = 
/**  yt-dlp, the extractor. */
"ytdlp" | 
/**  ffmpeg, the muxer and transcoder. */
"ffmpeg";

/**  Result of installing one external tool. */
export type ToolInstallResult = {
	/**  Which tool this entry is about. */
	tool: Tool,
	/**  Whether the install completed. */
	success: boolean,
	/**  Failure reason when `success` is false. */
	error?: string | null,
};

/**
 *  Installed state of one external tool.
 * 
 *  Three of the four fields are absent rather than false when unknown, and that
 *  is load-bearing: `updateAvailable` is `undefined` for a tool that is not
 *  installed, which the settings panel renders differently from "no update".
 */
export type ToolStatus = {
	/**  Whether the tool is present on disk. */
	installed: boolean,
	/**  The installed version, when it could be read. */
	version?: string | null,
	/**  The newest published version, when the upstream could be reached. */
	latestVersion?: string | null,
	/**  Whether an update is available. Absent when the tool is not installed. */
	updateAvailable?: boolean | null,
};

